import { MDFile } from '../../types';
import { mdFiles } from '../../utils/constants';

interface MDTabProps {
  selectedMDFile: MDFile | null;
  mdContent: string;
  setMdContent: (value: string) => void;
  mdFileExists: boolean;
  loadRealMDFile: (file: MDFile) => void;
  saveRealMDFile: () => void;
}

export default function MDTab({
  selectedMDFile, mdContent, setMdContent, mdFileExists,
  loadRealMDFile, saveRealMDFile,
}: MDTabProps) {
  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold">📝 Документация</h2>

      <div className="grid md:grid-cols-4 gap-4">
        {mdFiles.map(file => (
          <button
            key={file.name}
            onClick={() => loadRealMDFile(file)}
            className={`rounded-xl border-2 p-4 text-left transition-all ${
              selectedMDFile?.name === file.name
                ? 'border-emerald-500/50 bg-emerald-500/5'
                : 'border-gray-700 bg-gray-900/50 hover:border-gray-600'
            }`}
          >
            <h3 className="font-bold text-white text-base mb-2">{file.name}</h3>
            <p className="text-xs text-gray-400">{file.description}</p>
          </button>
        ))}
      </div>

      {selectedMDFile && (
        <div className="rounded-xl border border-gray-700 bg-gray-900/50 p-6">
          <div className="flex justify-between items-center mb-4">
            <h3 className="text-lg font-bold text-gray-300">📝 {selectedMDFile.name}</h3>
            <button
              onClick={saveRealMDFile}
              className="px-4 py-2 rounded-lg bg-emerald-500 hover:bg-emerald-600 text-white text-sm font-bold"
            >
              💾 Сохранить
            </button>
          </div>
          {!mdFileExists && (
            <div className="mb-4 p-3 rounded-lg bg-yellow-500/10 border border-yellow-500/30 text-yellow-400 text-sm">
              ⚠️ Файл не существует. Напишите содержимое и нажмите "Сохранить".
            </div>
          )}
          <textarea
            value={mdContent}
            onChange={(e) => setMdContent(e.target.value)}
            placeholder="Начните писать..."
            className="w-full h-96 px-4 py-3 rounded-lg bg-gray-800 border border-gray-700 text-white text-sm font-mono focus:border-emerald-500 focus:outline-none resize-none"
          />
          <div className="mt-2 text-xs text-gray-500">
            Символов: {mdContent.length} | Строк: {mdContent.split('\n').length}
          </div>
        </div>
      )}
    </div>
  );
}

import { CodeIssue } from '../../types';

interface CodeTabProps {
  codeIssues: CodeIssue[];
  fixCodeIssue: (id: number) => void;
  fixAll: () => void;
}

export default function CodeTab({ codeIssues, fixCodeIssue, fixAll }: CodeTabProps) {
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold">Анализ кода</h2>
        <button
          onClick={fixAll}
          className="px-4 py-2 rounded-lg bg-gradient-to-r from-red-500 to-orange-500 text-white text-sm font-bold"
        >
          🔧 Исправить все
        </button>
      </div>

      {codeIssues.map(issue => (
        <div
          key={issue.id}
          className={`rounded-xl border p-6 ${
            issue.fixed
              ? 'border-emerald-500/30 bg-emerald-500/5'
              : issue.severity === 'critical'
              ? 'border-red-500/30 bg-red-500/5'
              : issue.severity === 'warning'
              ? 'border-yellow-500/30 bg-yellow-500/5'
              : 'border-blue-500/30 bg-blue-500/5'
          }`}
        >
          <div className="flex justify-between items-start mb-3">
            <div>
              <div className="flex items-center gap-3 mb-2">
                <span
                  className={`px-2 py-1 rounded text-xs font-bold ${
                    issue.severity === 'critical'
                      ? 'bg-red-500/20 text-red-400'
                      : issue.severity === 'warning'
                      ? 'bg-yellow-500/20 text-yellow-400'
                      : 'bg-blue-500/20 text-blue-400'
                  }`}
                >
                  {issue.severity.toUpperCase()}
                </span>
                <span className="text-xs text-gray-500 font-mono">
                  {issue.file}:{issue.line}
                </span>
                {issue.fixed && (
                  <span className="px-2 py-1 rounded text-xs font-bold bg-emerald-500/20 text-emerald-400">
                    ИСПРАВЛЕНО
                  </span>
                )}
              </div>
              <h4 className="text-base font-bold text-white">{issue.title}</h4>
              <p className="text-sm text-gray-400 mt-2">{issue.description}</p>
            </div>
            {!issue.fixed && (
              <button
                onClick={() => fixCodeIssue(issue.id)}
                className="px-4 py-2 rounded-lg bg-emerald-500/20 border border-emerald-500/50 text-emerald-400 text-sm font-bold"
              >
                🔧 Исправить
              </button>
            )}
          </div>
          {issue.fixed && issue.fixLog && issue.fixLog.length > 0 && (
            <div className="mt-4 p-4 rounded-lg bg-gray-900/80 border border-gray-700">
              <div className="space-y-1 max-h-96 overflow-y-auto">
                {issue.fixLog.map((log, i) => (
                  <p key={i} className="text-xs text-gray-400 font-mono whitespace-pre-wrap">
                    {log}
                  </p>
                ))}
              </div>
            </div>
          )}
        </div>
      ))}
    </div>
  );
}

import { LogEntry } from '../../types';

interface LogsTabProps {
  logs: LogEntry[];
}

export default function LogsTab({ logs }: LogsTabProps) {
  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <h2 className="text-2xl font-bold">Логи</h2>
        <span className="text-xs text-gray-500">Обновление каждые 3 сек</span>
      </div>

      <div className="rounded-xl border border-gray-800 bg-gray-900/50 p-4 max-h-[70vh] overflow-y-auto">
        {logs.slice().reverse().map((entry, i) => (
          <div
            key={i}
            className="flex items-start gap-3 py-2 font-mono text-sm border-b border-gray-800/30 last:border-0"
          >
            <span className="text-gray-600 shrink-0">[{entry.time}]</span>
            <span
              className={
                entry.level === 'info'
                  ? 'text-blue-400'
                  : entry.level === 'warn'
                  ? 'text-yellow-400'
                  : entry.level === 'error'
                  ? 'text-red-400'
                  : 'text-emerald-400'
              }
            >
              {entry.level === 'info' ? 'ℹ' : entry.level === 'warn' ? '⚠' : entry.level === 'error' ? '✕' : '✓'}
            </span>
            <div className="flex-1">
              <span className="text-gray-300">{entry.message}</span>
              {entry.details && <p className="text-xs text-gray-500 mt-1">{entry.details}</p>}
            </div>
            <span className="text-gray-600 shrink-0">({entry.source})</span>
          </div>
        ))}
      </div>
    </div>
  );
}

import { Task } from '../../types';

interface TasksTabProps {
  taskList: Task[];
  newTaskText: string;
  setNewTaskText: (value: string) => void;
  newTaskPriority: 'high' | 'medium' | 'low';
  setNewTaskPriority: (value: 'high' | 'medium' | 'low') => void;
  newTaskCategory: 'code' | 'general';
  setNewTaskCategory: (value: 'code' | 'general') => void;
  addTask: () => void;
  toggleTask: (id: number) => void;
  deleteTask: (id: number) => void;
  codeTasks: Task[];
  generalTasks: Task[];
}

function TaskRow({
  task,
  onToggle,
  onDelete,
}: {
  task: Task;
  onToggle: () => void;
  onDelete: () => void;
}) {
  return (
    <div className="flex items-center gap-3 py-3 border-b border-gray-800/50 last:border-0">
      <button
        onClick={onToggle}
        className={`w-6 h-6 rounded border-2 flex items-center justify-center ${
          task.done ? 'bg-emerald-500 border-emerald-500 text-white' : 'border-gray-600'
        }`}
      >
        {task.done && '✓'}
      </button>
      <span className={`text-sm flex-1 ${task.done ? 'text-gray-500 line-through' : 'text-gray-200'}`}>
        {task.text}
      </span>
      <span
        className={`px-2 py-1 rounded text-xs font-bold ${
          task.priority === 'high'
            ? 'bg-red-500/20 text-red-400'
            : task.priority === 'medium'
            ? 'bg-yellow-500/20 text-yellow-400'
            : 'bg-gray-500/20 text-gray-400'
        }`}
      >
        {task.priority.toUpperCase()}
      </span>
      <button onClick={onDelete} className="text-red-400 hover:text-red-300 text-sm">
        ✕
      </button>
    </div>
  );
}

export default function TasksTab({
  taskList, newTaskText, setNewTaskText,
  newTaskPriority, setNewTaskPriority,
  newTaskCategory, setNewTaskCategory,
  addTask, toggleTask, deleteTask,
  codeTasks, generalTasks,
}: TasksTabProps) {
  return (
    <div className="space-y-6">
      <h2 className="text-2xl font-bold">Задачи</h2>

      <div className="rounded-xl border border-gray-700 bg-gray-900/50 p-6">
        <h3 className="text-lg font-bold mb-4">➕ Добавить задачу</h3>
        <div className="space-y-3">
          <input
            type="text"
            value={newTaskText}
            onChange={(e) => setNewTaskText(e.target.value)}
            placeholder="Описание задачи..."
            className="w-full px-4 py-3 rounded-lg bg-gray-800 border border-gray-700 text-white text-sm focus:border-emerald-500 focus:outline-none"
          />
          <div className="flex gap-3">
            <select
              value={newTaskPriority}
              onChange={(e) => setNewTaskPriority(e.target.value as any)}
              className="px-4 py-2 rounded-lg bg-gray-800 border border-gray-700 text-white text-sm"
            >
              <option value="high">🔴 Высокий</option>
              <option value="medium">🟡 Средний</option>
              <option value="low">🔵 Низкий</option>
            </select>
            <select
              value={newTaskCategory}
              onChange={(e) => setNewTaskCategory(e.target.value as any)}
              className="px-4 py-2 rounded-lg bg-gray-800 border border-gray-700 text-white text-sm"
            >
              <option value="code">⟨⟩ Исправление кода</option>
              <option value="general">📋 Общая задача</option>
            </select>
            <button
              onClick={addTask}
              className="px-6 py-2 rounded-lg bg-emerald-500 text-white text-sm font-bold"
            >
              Добавить
            </button>
          </div>
        </div>
      </div>

      <div className="rounded-xl border border-red-500/30 bg-red-500/5 p-6">
        <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
          <span>⟨⟩</span> Задачи по коду ({codeTasks.filter(t => !t.done).length})
        </h3>
        <div className="space-y-3">
          {codeTasks.map(task => (
            <TaskRow
              key={task.id}
              task={task}
              onToggle={() => toggleTask(task.id)}
              onDelete={() => deleteTask(task.id)}
            />
          ))}
        </div>
      </div>

      <div className="rounded-xl border border-blue-500/30 bg-blue-500/5 p-6">
        <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
          <span>📋</span> Общие задачи ({generalTasks.filter(t => !t.done).length})
        </h3>
        <div className="space-y-3">
          {generalTasks.map(task => (
            <TaskRow
              key={task.id}
              task={task}
              onToggle={() => toggleTask(task.id)}
              onDelete={() => deleteTask(task.id)}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

import { PatchInfo } from '../../types';
import { PatchStats } from '../../services/api';
import Modal from '../ui/Modal';

interface PatchesTabProps {
  patches: PatchInfo[];
  patchStats: PatchStats;
  selectedPatch: PatchInfo | null;
  patchPreview: any;
  applyingPatch: boolean;
  patchFilter: 'all' | 'pending' | 'applied' | 'errors';
  setPatchFilter: (filter: 'all' | 'pending' | 'applied' | 'errors') => void;
  patchLog: string[];
  previewPatch: (patch: PatchInfo) => void;
  applyPatch: (patch: PatchInfo) => void;
  rollbackLastPatch: () => void;
  archivePatch: (filename: string) => void;
  deletePatch: (filename: string) => void;
  applyAllPending: () => void;
  setSelectedPatch: (patch: PatchInfo | null) => void;
  setPatchPreview: (preview: any) => void;
}

export default function PatchesTab({
  patches, patchStats, selectedPatch, patchPreview, applyingPatch,
  patchFilter, setPatchFilter, patchLog,
  previewPatch, applyPatch, rollbackLastPatch,
  archivePatch, deletePatch, applyAllPending,
  setSelectedPatch, setPatchPreview,
}: PatchesTabProps) {
  const filteredPatches = patches.filter(p => {
    if (patchFilter === 'pending') return !p.is_applied && !p.error;
    if (patchFilter === 'applied') return p.is_applied;
    if (patchFilter === 'errors') return p.error;
    return true;
  });

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold">🔄 Система автопатчей</h2>
          <p className="text-sm text-gray-400 mt-1">Сканирование patch/ каждые 5 сек</p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={rollbackLastPatch}
            className="px-4 py-2 rounded-lg bg-red-500/20 border border-red-500/50 text-red-400 text-sm font-bold hover:bg-red-500/30"
          >
            ↩ Откатить
          </button>
          <button
            onClick={applyAllPending}
            disabled={applyingPatch || !patchStats.pending}
            className="px-4 py-2 rounded-lg bg-gradient-to-r from-emerald-500 to-cyan-500 text-white text-sm font-bold disabled:opacity-50"
          >
            ⚡ Применить все ({patchStats.pending || 0})
          </button>
        </div>
      </div>

      <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
        <div className="rounded-xl border border-gray-700 bg-gray-900/50 p-4">
          <div className="text-xs text-gray-500">Всего</div>
          <div className="text-2xl font-bold text-white">{patchStats.total || 0}</div>
        </div>
        <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/5 p-4">
          <div className="text-xs text-emerald-400">Применено</div>
          <div className="text-2xl font-bold text-emerald-400">{patchStats.applied || 0}</div>
        </div>
        <div className="rounded-xl border border-yellow-500/30 bg-yellow-500/5 p-4">
          <div className="text-xs text-yellow-400">Ожидают</div>
          <div className="text-2xl font-bold text-yellow-400">{patchStats.pending || 0}</div>
        </div>
        <div className="rounded-xl border border-red-500/30 bg-red-500/5 p-4">
          <div className="text-xs text-red-400">С ошибками</div>
          <div className="text-2xl font-bold text-red-400">{patchStats.errors || 0}</div>
        </div>
        <div className="rounded-xl border border-blue-500/30 bg-blue-500/5 p-4">
          <div className="text-xs text-blue-400">Бэкапов</div>
          <div className="text-2xl font-bold text-blue-400">{patchStats.backups_count || 0}</div>
        </div>
      </div>

      <div className="flex gap-2">
        {(['all', 'pending', 'applied', 'errors'] as const).map(f => (
          <button
            key={f}
            onClick={() => setPatchFilter(f)}
            className={`px-4 py-2 rounded-lg text-sm font-bold transition-all ${
              patchFilter === f
                ? 'bg-emerald-500/20 text-emerald-400 border border-emerald-500/50'
                : 'bg-gray-800 text-gray-400 border border-gray-700'
            }`}
          >
            {f === 'all' ? '📋 Все' : f === 'pending' ? '⏳ Ожидают' : f === 'applied' ? '✅ Применены' : '❌ С ошибками'}
          </button>
        ))}
      </div>

      <div className="space-y-3">
        {filteredPatches.map(patch => (
          <div
            key={patch.filename}
            className={`rounded-xl border-2 p-4 transition-all ${
              patch.is_applied
                ? 'border-emerald-500/30 bg-emerald-500/5'
                : patch.error
                ? 'border-red-500/30 bg-red-500/5'
                : 'border-gray-700 bg-gray-900/50 hover:border-cyan-500/30'
            }`}
          >
            <div className="flex justify-between items-start gap-4">
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-3 mb-2 flex-wrap">
                  <span className="px-2 py-1 rounded bg-gray-800 text-xs font-mono text-cyan-400">
                    #{patch.patch_id}
                  </span>
                  <span className="font-bold text-white truncate">{patch.target_file}</span>
                  {patch.is_applied && (
                    <span className="px-2 py-0.5 rounded text-xs bg-emerald-500/20 text-emerald-400">
                      ПРИМЕНЕН
                    </span>
                  )}
                  {patch.error && (
                    <span className="px-2 py-0.5 rounded text-xs bg-red-500/20 text-red-400">
                      ОШИБКА
                    </span>
                  )}
                </div>
                <p className="text-sm text-gray-400 mb-2">{patch.description}</p>
                <div className="flex gap-4 flex-wrap text-xs text-gray-500">
                  <span>👤 {patch.author}</span>
                  <span>📄 {patch.content_length} символов</span>
                </div>
              </div>
              <div className="flex gap-2 shrink-0">
                <button
                  onClick={() => previewPatch(patch)}
                  className="px-3 py-1.5 rounded bg-gray-700 hover:bg-gray-600 text-gray-300 text-xs font-bold"
                >
                  👁 Просмотр
                </button>
                {!patch.is_applied && !patch.error && (
                  <button
                    onClick={() => applyPatch(patch)}
                    disabled={applyingPatch}
                    className="px-3 py-1.5 rounded bg-emerald-500 hover:bg-emerald-600 text-white text-xs font-bold disabled:opacity-50"
                  >
                    ✅ Применить
                  </button>
                )}
                <button
                  onClick={() => archivePatch(patch.filename)}
                  className="px-3 py-1.5 rounded bg-blue-500/20 hover:bg-blue-500/30 text-blue-400 text-xs font-bold"
                >
                  📦
                </button>
                <button
                  onClick={() => deletePatch(patch.filename)}
                  className="px-3 py-1.5 rounded bg-red-500/20 hover:bg-red-500/30 text-red-400 text-xs font-bold"
                >
                  🗑
                </button>
              </div>
            </div>
          </div>
        ))}
        {patches.length === 0 && (
          <div className="text-center py-12 text-gray-500 border-2 border-dashed border-gray-700 rounded-xl">
            <p className="text-lg mb-2">📂 Папка patch/ пуста</p>
          </div>
        )}
      </div>

      <Modal
        isOpen={!!selectedPatch && !!patchPreview}
        onClose={() => {
          setSelectedPatch(null);
          setPatchPreview(null);
        }}
        title={selectedPatch ? `Превью патча #${selectedPatch.patch_id}` : ''}
      >
        {patchPreview?.success ? (
          <div className="space-y-4">
            <div className="p-4 rounded-lg bg-emerald-500/10 border border-emerald-500/30 text-emerald-400">
              ✅ {patchPreview.message}
            </div>
            <div className="grid grid-cols-2 gap-4 text-sm">
              <div className="p-3 rounded bg-gray-800">
                <div className="text-gray-500 text-xs">Старый размер</div>
                <div className="font-bold">
                  {patchPreview.old_size} байт / {patchPreview.old_lines} строк
                </div>
              </div>
              <div className="p-3 rounded bg-gray-800">
                <div className="text-gray-500 text-xs">Новый размер</div>
                <div className="font-bold">
                  {patchPreview.new_size} байт / {patchPreview.new_lines} строк
                </div>
              </div>
            </div>
            <div className="flex gap-3">
              <button
                onClick={() => {
                  setSelectedPatch(null);
                  setPatchPreview(null);
                }}
                className="flex-1 py-3 rounded-lg bg-gray-700 hover:bg-gray-600 text-white font-bold"
              >
                Отмена
              </button>
              <button
                onClick={() => {
                  if (selectedPatch) applyPatch(selectedPatch);
                  setSelectedPatch(null);
                  setPatchPreview(null);
                }}
                disabled={applyingPatch}
                className="flex-1 py-3 rounded-lg bg-gradient-to-r from-emerald-500 to-cyan-500 text-white font-bold disabled:opacity-50"
              >
                ✅ Применить
              </button>
            </div>
          </div>
        ) : patchPreview ? (
          <div className="p-4 rounded-lg bg-red-500/10 border border-red-500/30 text-red-400">
            ❌ {patchPreview.error}
          </div>
        ) : null}
      </Modal>
    </div>
  );
}
